using Avalonia;
using Avalonia.Controls;
using Avalonia.Media;
using Avalonia.Threading;
using Avalonia.VisualTree;
using VisualRelay.App.ViewModels;
using VisualRelay.App.Views;
using VisualRelay.App.Views.Controls;
using VisualRelay.Domain;

namespace VisualRelay.Tests;

/// <summary>
/// Headless visual-tree assertions for the round-task-cards-in-every-state
/// task.  Every assertion encodes a visual claim (chrome-free items, radius
/// invariants, day-header isolation) as a machine-checkable tree walk so the
/// gate does not need image inspection.
/// </summary>
[Collection("Headless")]
public sealed class TaskCardRenderTests
{
    private static readonly IBrush Transparent = Brushes.Transparent;

    // ══════════════════════════════════════════════════════════════════════
    // Chrome-free ListBoxItem tests (D1, D2)
    // ══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// In the default (non-selected, non-hovered, non-pressed) state, no
    /// element between each <c>ListBoxItem</c> root and its
    /// <c>Border.queueCard</c> paints a non-transparent Background.
    /// This catches the Fluent <c>ListBoxItem</c> chrome that paints square
    /// full-item highlight rectangles behind the rounded cards (D1/D2).
    /// </summary>
    [AvaloniaFact]
    public void ListBoxItems_HaveNoChromeBackground_InDefaultState()
    {
        var (window, _) = CreateWindowWithTasks();
        var items = GetTaskListBoxItems(window);

        Assert.True(items.Count >= 3,
            $"expected at least 3 ListBoxItems, found {items.Count}");

        foreach (var item in items)
        {
            var queueCard = FindQueueCard(item);
            Assert.NotNull(queueCard);

            var ancestors = AncestorsUpTo(queueCard, item);
            foreach (var ancestor in ancestors.OfType<Border>())
            {
                AssertBackgroundTransparent(ancestor,
                    $"ListBoxItem ancestor Border has non-transparent Background");
            }
        }
    }

    /// <summary>
    /// Forcing <c>:pointerover</c> and <c>:pressed</c> pseudo-classes on a
    /// <c>ListBoxItem</c> must not cause any element between the item root
    /// and its <c>Border.queueCard</c> to paint a non-transparent Background
    /// — state visuals belong exclusively to the card's bound properties (D2).
    /// </summary>
    [AvaloniaFact]
    public void ListBoxItems_HaveNoChromeBackground_UnderForcedPseudoStates()
    {
        var (window, vm) = CreateWindowWithTasks();
        var items = GetTaskListBoxItems(window);
        Assert.True(items.Count >= 2,
            $"expected at least 2 ListBoxItems, found {items.Count}");

        // Pick a non-selected item to test pseudo-classes in isolation.
        var testItem = items.First(i =>
            !ReferenceEquals(i.DataContext, vm.SelectedTask));

        var classes = (IPseudoClasses)testItem.Classes;
        classes.Set(":pointerover", true);
        Dispatcher.UIThread.RunJobs();

        var queueCard = FindQueueCard(testItem);
        Assert.NotNull(queueCard);
        var ancestors = AncestorsUpTo(queueCard, testItem);
        foreach (var ancestor in ancestors.OfType<Border>())
        {
            AssertBackgroundTransparent(ancestor,
                "ListBoxItem ancestor Border painted non-transparent Background under :pointerover");
        }

        classes.Set(":pressed", true);
        Dispatcher.UIThread.RunJobs();

        foreach (var ancestor in ancestors.OfType<Border>())
        {
            AssertBackgroundTransparent(ancestor,
                "ListBoxItem ancestor Border painted non-transparent Background under :pressed");
        }
    }

    /// <summary>
    /// When an item is genuinely selected through the ListBox, no element
    /// between the <c>ListBoxItem</c> root and its <c>Border.queueCard</c>
    /// paints a non-transparent Background — the selection highlight is
    /// delivered exclusively by the card's blue outer ring (D1).
    /// </summary>
    [AvaloniaFact]
    public void ListBoxItems_HaveNoChromeBackground_WhenSelected()
    {
        var (window, vm) = CreateWindowWithTasks();
        var selected = vm.SelectedTask;
        Assert.NotNull(selected);

        var items = GetTaskListBoxItems(window);
        var selectedItem = items.FirstOrDefault(i =>
            ReferenceEquals(i.DataContext, selected));
        Assert.NotNull(selectedItem);

        var queueCard = FindQueueCard(selectedItem);
        Assert.NotNull(queueCard);

        var ancestors = AncestorsUpTo(queueCard, selectedItem);
        foreach (var ancestor in ancestors.OfType<Border>())
        {
            AssertBackgroundTransparent(ancestor,
                "selected ListBoxItem ancestor Border has non-transparent Background");
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Day-header isolation (D5)
    // ══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// When a task row with a <c>DayHeader</c> is selected, the header
    /// <c>TextBlock</c>'s ancestors up to the item root still paint no
    /// background — the selection chrome must be card-scoped only (D5).
    /// </summary>
    [AvaloniaFact]
    public void DayHeader_IsUntinted_WhenSelected()
    {
        var (window, vm) = CreateWindowWithTasks();
        var items = GetTaskListBoxItems(window);

        // Find the item whose DataContext has a DayHeader.
        var dayItem = items.FirstOrDefault(i =>
            i.DataContext is TaskRowViewModel tr && !string.IsNullOrEmpty(tr.DayHeader));
        Assert.NotNull(dayItem);

        // Switch selection to the day-header task.
        var dayRow = (TaskRowViewModel)dayItem.DataContext!;
        vm.SelectedTask = dayRow;
        Dispatcher.UIThread.RunJobs();

        // Find the header TextBlock.
        var headerText = dayItem.GetVisualDescendants()
            .OfType<TextBlock>()
            .FirstOrDefault(tb => !string.IsNullOrEmpty(tb.Text) && tb.Text!.Contains("Today"));
        Assert.NotNull(headerText);

        // Walk ancestors of the header TextBlock up to the ListBoxItem.
        var ancestors = AncestorsUpTo(headerText, dayItem);
        foreach (var ancestor in ancestors.OfType<Border>())
        {
            AssertBackgroundTransparent(ancestor,
                $"DayHeader ancestor Border has non-transparent Background when selected");
        }
    }

    // ══════════════════════════════════════════════════════════════════════
    // Corner-radius invariants (D3, D4)
    // ══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// The outer highlight <c>Border</c>'s <c>CornerRadius</c> must equal the
    /// inner card's <c>CornerRadius</c> plus the outer ring's
    /// <c>BorderThickness</c> — this is the uniform-ring invariant (D3).
    /// </summary>
    [AvaloniaFact]
    public void CornerRadius_OuterRingEqualsCardPlusRingThickness()
    {
        var (window, vm) = CreateWindowWithTasks();
        var selected = vm.SelectedTask;
        Assert.NotNull(selected);

        var items = GetTaskListBoxItems(window);
        var selectedItem = items.First(i =>
            ReferenceEquals(i.DataContext, selected));

        var queueCard = FindQueueCard(selectedItem);
        Assert.NotNull(queueCard);

        // The outer highlight Border is the parent of the queueCard Border.
        var outerRing = queueCard.Parent as Border;
        Assert.NotNull(outerRing);

        var cardRadius = queueCard.CornerRadius.TopLeft;
        var outerRadius = outerRing.CornerRadius.TopLeft;
        var ringThickness = outerRing.BorderThickness.Left;

        Assert.Equal(cardRadius + ringThickness, outerRadius);
    }

    /// <summary>
    /// Pins the exact <c>CornerRadius</c> literals: outer ring 10, inner
    /// card 8, selection rail <c>7,0,0,7</c> (D3, D4).
    /// </summary>
    [AvaloniaFact]
    public void CornerRadius_LiteralsMatchSpec()
    {
        var (window, _) = CreateWindowWithTasks();
        var items = GetTaskListBoxItems(window);
        Assert.NotEmpty(items);

        var queueCard = FindQueueCard(items[0]);
        Assert.NotNull(queueCard);

        // Outer ring CornerRadius must be 10.
        var outerRing = queueCard.Parent as Border;
        Assert.NotNull(outerRing);
        Assert.Equal(new CornerRadius(10), outerRing.CornerRadius);

        // Inner card CornerRadius must be 8.
        Assert.Equal(new CornerRadius(8), queueCard.CornerRadius);

        // Selection rail CornerRadius must be 7,0,0,7 (left corners only).
        var rail = queueCard.GetVisualDescendants()
            .OfType<Border>()
            .FirstOrDefault(b => b.Classes.Contains("selectionRail"));
        Assert.NotNull(rail);
        Assert.Equal(new CornerRadius(7, 0, 0, 7), rail.CornerRadius);
    }

    // ══════════════════════════════════════════════════════════════════════
    // Helpers
    // ══════════════════════════════════════════════════════════════════════

    /// <summary>
    /// Creates a headless <see cref="MainWindow"/> with tasks covering all
    /// four card states (default / selected / running / running+selected)
    /// plus one item carrying a <c>DayHeader</c>.
    /// </summary>
    private static (MainWindow Window, MainWindowViewModel Vm) CreateWindowWithTasks()
    {
        var env = new DictionaryEnvironmentAccessor
        {
            ["XDG_CONFIG_HOME"] = Path.GetTempPath()
        };
        var vm = new MainWindowViewModel(env);

        var defaultTask = new TaskRowViewModel(NewTask("default-card"));
        var runningTask = new TaskRowViewModel(NewTask("running-card"));
        runningTask.MarkRunning();

        var combinedTask = new TaskRowViewModel(NewTask("combined-card"));
        combinedTask.MarkRunning();

        var dayHeaderTask = new TaskRowViewModel(NewTask("day-header-card"))
        {
            DayHeader = "Today ($1.04)"
        };

        vm.Tasks.Add(defaultTask);
        vm.Tasks.Add(runningTask);
        vm.Tasks.Add(combinedTask);
        vm.Tasks.Add(dayHeaderTask);

        // The combined task is selected so we get the running+selected state.
        vm.SelectedTask = combinedTask;

        var window = new MainWindow
        {
            DataContext = vm,
            Width = 1440,
            Height = 900
        };
        window.Show();
        Dispatcher.UIThread.RunJobs();
        return (window, vm);
    }

    private static List<ListBoxItem> GetTaskListBoxItems(MainWindow window)
    {
        var queuePanel = window.GetVisualDescendants()
            .OfType<QueuePanel>()
            .Single();
        var listBox = queuePanel.FindControl<ListBox>("TaskQueueList");
        Assert.NotNull(listBox);

        return listBox.GetVisualDescendants()
            .OfType<ListBoxItem>()
            .ToList();
    }

    /// <summary>
    /// Finds the <c>Border.queueCard</c> inside a <c>ListBoxItem</c>.
    /// </summary>
    private static Border? FindQueueCard(ListBoxItem item)
    {
        return item.GetVisualDescendants()
            .OfType<Border>()
            .FirstOrDefault(b => b.Classes.Contains("queueCard"));
    }

    /// <summary>
    /// Returns every visual ancestor of <paramref name="descendant"/> up to
    /// (but not including) <paramref name="root"/>.
    /// </summary>
    private static List<Visual> AncestorsUpTo(Visual descendant, Visual root)
    {
        var result = new List<Visual>();
        var current = descendant.GetVisualParent();
        while (current is not null && !ReferenceEquals(current, root))
        {
            result.Add(current);
            current = current.GetVisualParent();
        }

        return result;
    }

    /// <summary>
    /// Asserts that the <see cref="Border.Background"/> of
    /// <paramref name="border"/> is either <c>null</c> or a transparent
    /// solid-colour brush.
    /// </summary>
    private static void AssertBackgroundTransparent(Border border, string message)
    {
        var bg = border.Background;
        if (bg is null) return;
        if (bg == Transparent) return;
        if (bg is ISolidColorBrush solid && solid.Color.A == 0) return;

        Assert.Fail($"{message}. " +
            $"Border [{(border.Classes.Count > 0 ? string.Join(' ', border.Classes) : "<no classes>")}] " +
            $"has Background={bg}");
    }

    private static RelayTaskItem NewTask(string id) =>
        new(id, $"/tmp/{id}.md", "/tmp", false, [],
            CompletedStageCount: 0);
}

using System.Text.RegularExpressions;

namespace VisualRelay.Tests;

/// <summary>
/// Structural guard: the task-card <c>ControlTheme</c> that strips Fluent's
/// square <c>ListBoxItem</c> chrome must be referenced from the
/// <c>QueuePanel</c> list and must contain no pseudo-class setters that
/// would reintroduce square highlights behind the rounded cards.
///
/// These tests catch accidental removal or pollution of the theme so the
/// square chrome cannot silently return (D1, D2).
/// </summary>
public sealed class TaskCardThemeGuardTests
{
    private static string RepoRoot => RepoSetup.Root;
    private static string QueuePanelPath =>
        Path.Combine(RepoRoot, "src", "VisualRelay.App", "Views", "Controls", "QueuePanel.axaml");
    private static string ThemePath =>
        Path.Combine(RepoRoot, "src", "VisualRelay.App", "Styles", "VisualRelayTheme.axaml");

    /// <summary>
    /// The <c>TaskQueueList</c> <c>ListBox</c> in <c>QueuePanel.axaml</c>
    /// must declare <c>ItemContainerTheme</c> so it uses the scoped
    /// <c>TaskCardItemTheme</c> instead of Fluent's default chrome.
    /// </summary>
    [Fact]
    public void QueuePanel_TaskQueueList_DeclaresItemContainerTheme()
    {
        Assert.True(File.Exists(QueuePanelPath),
            $"QueuePanel.axaml not found at {QueuePanelPath}");

        var text = File.ReadAllText(QueuePanelPath);
        var lines = File.ReadAllLines(QueuePanelPath);

        // Find the line containing x:Name="TaskQueueList" and assert it also
        // contains ItemContainerTheme.
        for (var i = 0; i < lines.Length; i++)
        {
            if (lines[i].Contains("x:Name=\"TaskQueueList\""))
            {
                Assert.True(lines[i].Contains("ItemContainerTheme"),
                    $"Line {i + 1} of QueuePanel.axaml with x:Name=\"TaskQueueList\" " +
                    "does not declare ItemContainerTheme.\n" +
                    $"Full line: {lines[i].Trim()}");
                return;
            }
        }

        Assert.Fail("Could not find x:Name=\"TaskQueueList\" in QueuePanel.axaml");
    }

    /// <summary>
    /// The <c>TaskCardItemTheme</c> <c>ControlTheme</c> in
    /// <c>VisualRelayTheme.axaml</c> must contain NO
    /// <c>:pointerover</c> / <c>:pressed</c> / <c>:selected</c> pseudo-class
    /// setters — state visuals belong exclusively to the card's bound
    /// properties.
    /// </summary>
    [Fact]
    public void TaskCardItemTheme_HasNoPseudoClassSetters()
    {
        Assert.True(File.Exists(ThemePath),
            $"VisualRelayTheme.axaml not found at {ThemePath}");

        var lines = File.ReadAllLines(ThemePath);

        // Locate the TaskCardItemTheme ControlTheme block.
        var start = -1;
        var end = -1;
        for (var i = 0; i < lines.Length; i++)
        {
            if (lines[i].Contains("x:Key=\"TaskCardItemTheme\""))
            {
                start = i;
            }

            if (start >= 0 && lines[i].Contains("</ControlTheme>"))
            {
                end = i;
                break;
            }
        }

        Assert.True(start >= 0,
            "TaskCardItemTheme ControlTheme not found in VisualRelayTheme.axaml. " +
            "It must be defined with x:Key=\"TaskCardItemTheme\".");

        Assert.True(end >= 0,
            "TaskCardItemTheme ControlTheme has no closing </ControlTheme> tag.");

        var forbidden = new[] { ":pointerover", ":pressed", ":selected" };
        for (var i = start; i <= end; i++)
        {
            var line = lines[i];
            foreach (var pattern in forbidden)
            {
                if (line.Contains(pattern))
                {
                    Assert.Fail(
                        $"TaskCardItemTheme (line {i + 1}) contains forbidden " +
                        $"pseudo-class '{pattern}'. State visuals belong exclusively " +
                        $"to the card's bound properties.\n" +
                        $"Line: {line.Trim()}");
                }
            }
        }
    }
}

