/// <summary>
/// Asserts that the <see cref="Control.Background"/> of
/// <paramref name="control"/> is either <c>null</c> or a transparent
/// solid-colour brush.  Works on <see cref="Border"/> and
/// <see cref="ContentPresenter"/> alike — Fluent's
/// <c>ListBoxItem</c> template applies pseudo-class fills to the
/// <c>ContentPresenter</c>, not to a <c>Border</c>.
/// </summary>
private static void AssertBackgroundTransparent(Control control, string message)
{
    if (control is not Border && control is not ContentPresenter) return;

    var bg = control.Background;
    if (bg is null) return;
    if (bg == Transparent) return;
    if (bg is ISolidColorBrush solid && solid.Color.A == 0) return;

    var desc = control is Border b
        ? $"Border [{(b.Classes.Count > 0 ? string.Join(' ', b.Classes) : "<no classes>")}]"
        : $"{control.GetType().Name}";
    Assert.Fail($"{message}. {desc} has Background={bg}");
}

/// <summary>
/// Returns every visual ancestor of <paramref name="descendant"/> up to
/// (but not including) <paramref name="root"/> that is a
/// <see cref="Control"/>.
/// </summary>
private static List<Control> AncestorsUpTo(Control descendant, Visual root)
{
    var result = new List<Control>();
    var current = descendant.GetVisualParent();
    while (current is not null && !ReferenceEquals(current, root))
    {
        if (current is Control c) result.Add(c);
        current = current.GetVisualParent();
    }

    return result;
}

